<script setup lang="ts">
import {onBeforeUnmount,onMounted,reactive,ref} from 'vue'
import {useWorkspace} from '../../app/workspace'
import {createLatestRequests,isCancelled} from '../../shared/api/client'
import FormDialog from '../../shared/components/FormDialog.vue'
import {today,type Profile} from './types'
const props=defineProps<{person:Profile}>(),emit=defineEmits<{close:[];saved:[]}>()
const {api,command,can,captureSession}=useWorkspace(),requests=createLatestRequests(api)
const error=ref(''),busy=ref(false),users=ref<{id:string;name:string}[]>([])
const form=reactive({name:props.person.name,source:props.person.source,document_type:props.person.document_type||'',document_number:props.person.document_number||'',birth_date:props.person.birth_date||'',phone:props.person.phone||'',address:props.person.address||'',responsible_user_id:props.person.responsible_user_id||''})
async function save(){busy.value=true;error.value='';const valid=captureSession();try{await command('person-profile-'+props.person.id,`/person-drafts/${props.person.id}/update`,{version:props.person.version,name:form.name,source:form.source,responsible_user_id:form.responsible_user_id||null,...(can('persons.identity')?{document_type:form.document_type||null,document_number:form.document_number||null,birth_date:form.birth_date||null,phone:form.phone,address:form.address}:{})});if(valid())emit('saved')}catch(e){if(!isCancelled(e))error.value=e instanceof Error?e.message:'保存失败'}finally{busy.value=false}}
onMounted(async()=>{try{users.value=(await requests.latest<{users:typeof users.value}>('options','/person-drafts/options')).users}catch(e){if(!isCancelled(e))error.value=e instanceof Error?e.message:'责任人选项加载失败'}});onBeforeUnmount(()=>requests.dispose())
</script>
<template><FormDialog title="维护人员主档" :wide="true" :busy="busy" :error="error" @close="emit('close')"><form @submit.prevent="save"><div class="person-form-grid"><label>名称<input v-model="form.name" maxlength="120" required></label><label>来源<input v-model="form.source" maxlength="200" required></label><label>责任人<select v-model="form.responsible_user_id"><option value="">暂未指定</option><option v-for="user in users" :key="user.id" :value="user.id">{{user.name}}</option></select></label><template v-if="can('persons.identity')"><label>证件类型<select v-model="form.document_type"><option value="">暂不填写</option><option value="NATIONAL_ID">居民身份证</option><option value="PASSPORT">护照</option><option value="OTHER">其他身份依据</option></select></label><label>证件 / 身份依据编号<input v-model="form.document_number" maxlength="100" :required="!!form.document_type"></label><label>出生日期<input v-model="form.birth_date" type="date" :max="today()"></label><label>联系电话<input v-model="form.phone" maxlength="100"></label></template></div><label v-if="can('persons.identity')">联系地址<textarea v-model="form.address" maxlength="1000"></textarea></label><p class="muted person-hint">主档更正后身份恢复待核验，业务记录和历史不会被覆盖；系统不会按姓名自动合并人员。</p><button :disabled="busy">保存主档</button></form></FormDialog></template>
